// native-mate: chip@0.5.0 | hash:96f736649d91c270
import React, { useCallback, useEffect } from 'react'
import { View, Pressable } from 'react-native'
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  interpolateColor,
} from 'react-native-reanimated'
import { Ionicons } from '@expo/vector-icons'
import { useTheme, Text, makeStyles, fontStyle, useHaptics, deprecatedProp, useDirection } from '@native-mate/core'
import type { ChipProps, ChipGroupProps } from './chip.types'

const sizeMap = {
  sm: { height: 28, px: 10, fontSize: 12, iconSize: 14, closeSize: 14 },
  md: { height: 34, px: 14, fontSize: 14, iconSize: 16, closeSize: 16 },
}

const useStyles = makeStyles((theme) => ({
  chip: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 9999,
    overflow: 'hidden',
  },
  disabled: {
    opacity: 0.5,
  },
}))

const AnimatedView = Animated.View

export const Chip = React.memo<ChipProps>(({
  label,
  selected = false,
  onPress,
  variant = 'outlined',
  size = 'md',
  icon,
  avatar,
  closable = false,
  onClose,
  disabled = false,
  color,
  haptic = 'light',
  style,
  testID,
}) => {
  const theme = useTheme()
  const styles = useStyles()
  const haptics = useHaptics()
  const { isRTL } = useDirection()
  const dims = sizeMap[size]

  const selectionProgress = useSharedValue(selected ? 1 : 0)
  const scale = useSharedValue(1)

  const accentColor = color ?? theme.colors.primary

  useEffect(() => {
    selectionProgress.value = withSpring(selected ? 1 : 0, {
      damping: 16,
      stiffness: 240,
    })
  }, [selected])

  const filledAnimStyle = useAnimatedStyle(() => {
    if (variant === 'filled') {
      const backgroundColor = interpolateColor(
        selectionProgress.value,
        [0, 1],
        [theme.colors.surface, accentColor],
      )
      return {
        backgroundColor,
        transform: [{ scale: scale.value }],
      }
    }
    // outlined
    const backgroundColor = interpolateColor(
      selectionProgress.value,
      [0, 1],
      ['transparent', accentColor + '18'],
    )
    const borderColor = interpolateColor(
      selectionProgress.value,
      [0, 1],
      [theme.colors.border, accentColor],
    )
    return {
      backgroundColor,
      borderColor,
      borderWidth: 1,
      transform: [{ scale: scale.value }],
    }
  })

  const textColor = variant === 'filled' && selected
    ? theme.colors.onPrimary
    : selected
      ? accentColor
      : theme.colors.foreground

  const iconColor = variant === 'filled' && selected
    ? theme.colors.onPrimary
    : selected
      ? accentColor
      : theme.colors.muted

  const handlePressIn = useCallback(() => {
    scale.value = withSpring(0.93, { damping: 15, stiffness: 300 })
    haptics.trigger(haptic)
  }, [haptic, haptics])

  const handlePressOut = useCallback(() => {
    scale.value = withSpring(1, { damping: 15, stiffness: 300 })
  }, [])

  // Chips are 28–34pt tall, well under the 44pt minimum touch target. hitSlop
  // extends the *touchable* area without altering the rendered size. Horizontal
  // slop is kept small so adjacent chips in a ChipGroup can't steal each
  // other's taps.
  const chipHitSlop = {
    top: Math.max(0, Math.ceil((44 - dims.height) / 2)),
    bottom: Math.max(0, Math.ceil((44 - dims.height) / 2)),
    left: 4,
    right: 4,
  }

  // Close icon is 14–16pt; slop reaches ~44pt while biasing away from the label
  // so the main press target isn't swallowed. `hitSlop` has no logical spelling
  // — RN only accepts physical left/right here and never mirrors them — so the
  // asymmetric bias is swapped by hand under RTL, where the row (and with it the
  // label the slop must lean away from) has flipped to the other side.
  const towardLabel = 10
  const awayFromLabel = Math.max(0, 44 - dims.closeSize - 10)
  const closeHitSlop = {
    top: Math.max(0, Math.ceil((44 - dims.closeSize) / 2)),
    bottom: Math.max(0, Math.ceil((44 - dims.closeSize) / 2)),
    left: isRTL ? awayFromLabel : towardLabel,
    right: isRTL ? towardLabel : awayFromLabel,
  }

  const handleClose = useCallback(() => {
    haptics.trigger(haptic)
    onClose?.()
  }, [haptic, onClose, haptics])

  return (
    <AnimatedView
      testID={testID}
      style={[
        styles.chip,
        {
          height: dims.height,
          paddingStart: avatar ? 4 : dims.px,
          paddingEnd: closable ? 6 : dims.px,
          gap: 6,
        },
        variant === 'outlined' && !selected && {
          borderWidth: 1,
          borderColor: theme.colors.border,
        },
        disabled && styles.disabled,
        filledAnimStyle,
        style,
      ]}
    >
      {/* Main pressable content — the close button below is a sibling, not a
          descendant, so the parent's press-in scale/haptic can't be stolen by it. */}
      <Pressable
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled}
        hitSlop={chipHitSlop}
        accessibilityRole="button"
        accessibilityLabel={label}
        accessibilityState={{ selected, disabled }}
        style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}
      >
        {/* Avatar */}
        {avatar && (
          <View style={{ marginEnd: -2 }}>{avatar}</View>
        )}

        {/* Icon — a string still renders through Ionicons for one minor. */}
        {icon != null && !avatar && (
          typeof icon === 'string'
            ? (
              <Ionicons
                name={deprecatedProp('Chip icon (string)', 'Chip icon (ReactNode)', icon) as any}
                size={dims.iconSize}
                color={iconColor}
              />
            )
            : icon
        )}

        {/* Checkmark for selected state */}
        {selected && !icon && !avatar && (
          <Ionicons name="checkmark" size={dims.iconSize} color={iconColor} />
        )}

        {/* Label */}
        <Text
          style={{ fontSize: dims.fontSize, ...fontStyle(theme.typography, 'medium'), color: textColor }}
          numberOfLines={1}
        >
          {label}
        </Text>
      </Pressable>

      {/* Close button — sibling of the main Pressable, outside its subtree */}
      {closable && (
        <Pressable
          onPress={handleClose}
          hitSlop={closeHitSlop}
          disabled={disabled}
          accessibilityRole="button"
          accessibilityLabel={`Remove ${label}`}
          testID={testID ? `${testID}-close` : undefined}
        >
          <Ionicons name="close-circle" size={dims.closeSize} color={iconColor} style={{ opacity: 0.7 }} />
        </Pressable>
      )}
    </AnimatedView>
  )
})

Chip.displayName = 'Chip'

export const ChipGroup: React.FC<ChipGroupProps> = ({
  children,
  wrap = true,
  gap = 8,
  style,
  testID,
}) => (
  <View
    style={[
      {
        flexDirection: 'row',
        flexWrap: wrap ? 'wrap' : 'nowrap',
        gap,
      },
      style,
    ]}
    accessibilityRole="radiogroup"
    testID={testID}
  >
    {children}
  </View>
)

// native-mate: chip@0.5.0 | hash:751481432eff18e9
import type React from 'react'
import type { StyleProp, ViewStyle } from 'react-native'
import type { HapticProp, IconProp } from '@native-mate/core'

export type ChipVariant = 'filled' | 'outlined'
export type ChipSize = 'sm' | 'md'

// Canonical home is '@native-mate/core'; re-exported for source compatibility.
export type { HapticStyle, HapticProp, IconProp } from '@native-mate/core'

export interface ChipProps {
  label: string
  selected?: boolean
  onPress?: () => void
  variant?: ChipVariant
  size?: ChipSize
  /**
   * Node rendered before the label. A string is still accepted for one minor
   * and rendered through Ionicons — deprecated, pass an element instead.
   */
  icon?: IconProp
  /** Avatar node displayed before the label */
  avatar?: React.ReactNode
  /** Show a close/remove button */
  closable?: boolean
  onClose?: () => void
  disabled?: boolean
  /** Custom selected color */
  color?: string
  /** `false` (or 'none') disables haptics for this chip; `true` means 'light'. */
  haptic?: HapticProp
  style?: StyleProp<ViewStyle>
  testID?: string
}

export interface ChipGroupProps {
  children: React.ReactNode
  /** Wrap chips to next line */
  wrap?: boolean
  /** Gap between chips */
  gap?: number
  style?: StyleProp<ViewStyle>
  testID?: string
}
